function Logo() { return <div className="flex items-center gap-2.5"><div className="brand-mark"><span /><span /><span /></div><span className="text-[15px] font-extrabold tracking-[-.04em] text-white">ShikshaSetu</span></div>; }
function Button({ children, onClick, variant = "primary", className = "" }: { children: React.ReactNode; onClick?: () => void; variant?: "primary" | "outline" | "ghost"; className?: string }) { return <button onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2.5 text-[11px] font-bold transition active:scale-[.98] ${variant === "primary" ? "bg-[#efede8] text-[#0a0a0b] hover:bg-white" : variant === "outline" ? "border border-white/12 bg-white/[.035] text-white hover:bg-white/[.08]" : "text-white/55 hover:bg-white/[.06] hover:text-white"} ${className}`}>{children}</button>; }
function Glass({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <div className={`glass-surface rounded-xl ${className}`}>{children}</div>; }
function Eyebrow({ children }: { children: React.ReactNode }) { return <div className="eyebrow">{children}</div>; }
function Status({ children, tone = "neutral" }: { children: React.ReactNode; tone?: Tone }) { const c = { green: "bg-[#8eaa95]/15 text-[#abd0b0]", violet: "bg-[#a28ad6]/15 text-[#c1aeeb]", amber: "bg-[#b29363]/15 text-[#d8ba84]", red: "bg-[#b46e6e]/15 text-[#dc9b9b]", neutral: "bg-white/[.08] text-white/45" }; return <span className={`rounded-md px-2 py-1 text-[9px] font-mono uppercase tracking-wider ${c[tone]}`}>{children}</span>; }
function Progress({ value, color = "bg-[#a890dc]" }: { value: number; color?: string }) { return <div className="h-1.5 overflow-hidden rounded-full bg-white/[.08]"><div className={`h-full rounded-full ${color}`} style={{ width: `${Math.min(value, 100)}%` }} /></div>; }
function Title({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><Eyebrow>{eyebrow}</Eyebrow><h1 className="mt-3 text-3xl font-bold tracking-[-.065em] text-white md:text-4xl">{title}</h1>{subtitle && <p className="mt-2 max-w-2xl text-sm leading-6 text-white/40">{subtitle}</p>}</div>{action}</div>; }

function Shell({ role, page, onCommand, children }: { role: Role; page: string; onCommand: () => void; children: React.ReactNode }) { const navigate = useNavigate(); const meta = roleMeta[role]; return <div className="min-h-screen bg-[#080809] text-[#f2f0ed]"><aside className="fixed inset-y-0 left-0 z-30 hidden w-[234px] flex-col border-r border-white/10 bg-[#0b0b0d]/95 px-4 py-5 backdrop-blur-xl lg:flex"><Logo /><div className="mt-8 rounded-lg border border-white/10 bg-white/[.025] p-1"><div className="px-2 py-1 text-[9px] font-mono uppercase tracking-[.18em] text-white/30">Operating mode</div>{(Object.keys(roleMeta) as Role[]).map(r => <button key={r} onClick={() => navigate(`/app/${r}/${nav[r][0].slug}`)} className={`flex w-full items-center justify-between rounded-md px-2 py-2 text-[11px] font-semibold ${role === r ? "bg-white/10 text-white" : "text-white/40 hover:text-white"}`}>{roleMeta[r].label}{role === r && <span className="h-1.5 w-1.5 rounded-full bg-[#b69ce7]" />}</button>)}</div><div className="mt-7 flex-1 space-y-1 overflow-y-auto pr-1">{nav[role].map(item => { const I = item.icon; return <button key={item.slug} onClick={() => navigate(`/app/${role}/${item.slug}`)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-[11px] font-semibold ${item.slug === page ? "bg-[#9b7dcc]/15 text-white" : "text-white/40 hover:bg-white/[.045] hover:text-white"}`}><I size={15} />{item.label}{item.slug === "roadmap" && <span className="ml-auto text-[9px] text-[#bba4e8]">LIVE</span>}</button>; })}</div><div className="mt-auto space-y-1 border-t border-white/10 pt-4"><button className="flex w-full items-center gap-3 px-3 py-2 text-[11px] text-white/40"><CircleHelp size={15} />Help center</button><button className="flex w-full items-center gap-3 px-3 py-2 text-[11px] text-white/40"><Settings2 size={15} />Preferences</button><div className="mt-3 flex items-center gap-2 rounded-lg bg-white/[.04] p-2"><div className="flex h-7 w-7 items-center justify-center rounded-full bg-[#d5c6ed] text-[10px] font-bold text-[#17121e]">{meta.initials}</div><div className="min-w-0"><div className="truncate text-[10px] font-bold text-white">{meta.name}</div><div className="text-[9px] text-white/35">{meta.subtitle}</div></div></div></div></aside><div className="lg:pl-[234px]"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-white/10 bg-[#080809]/88 px-5 backdrop-blur-xl md:px-8"><div className="flex items-center gap-3 lg:hidden"><Logo /></div><div className="hidden text-[11px] text-white/35 lg:block"><span className="text-white/75">{meta.label} workspace</span><span className="mx-2">/</span>{page.replace(/-/g, " ")}</div><button onClick={onCommand} className="ml-auto flex w-full max-w-[340px] items-center gap-3 rounded-lg border border-white/10 bg-white/[.035] px-3 py-2 text-[11px] text-white/35 hover:border-white/20 md:ml-0"><Search size={14} /><span>Search skills, roles, opportunities...</span><span className="ml-auto hidden items-center gap-1 rounded border border-white/10 px-1.5 py-0.5 font-mono text-[9px] text-white/35 sm:flex"><Command size={10} />K</span></button><div className="ml-4 hidden items-center gap-4 sm:flex"><Bell size={16} className="text-white/45" /><div className="h-7 w-7 rounded-full bg-[#d5c6ed] text-center text-[10px] font-bold leading-7 text-[#17121e]">{meta.initials}</div></div></header><main className="mx-auto max-w-[1450px] px-5 py-8 md:px-8 md:py-10">{children}</main></div></div>; }
function CommandPalette({ close }: { close: () => void }) { const [query, setQuery] = useState(""); const result = query.toLowerCase().includes("docker") ? [["Docker", "Skill · 12 courses · 219 opportunities", Fingerprint], ["MLOps Engineer", "Role · 64 opportunities", BriefcaseBusiness], ["Cloud Bridge Program", "Intervention · 300 students", Zap]] : [["AI / ML Engineer", "Role · 1,284 candidates ready", BriefcaseBusiness], ["Docker", "Skill · critical gap for Aanya", Fingerprint], ["Aanya Sharma", "Student · 72% readiness", Users]]; return <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/70 px-4 pt-[16vh] backdrop-blur-sm" onClick={close}><div className="w-full max-w-[620px] rounded-xl border border-white/15 bg-[#141416] p-3 shadow-2xl" onClick={e => e.stopPropagation()}><div className="flex items-center gap-3 border-b border-white/10 px-3 pb-3"><Search size={17} className="text-white/35" /><input autoFocus value={query} onChange={e => setQuery(e.target.value)} placeholder="Search skills, roles, opportunities..." className="w-full bg-transparent text-sm text-white outline-none placeholder:text-white/30" /><span className="font-mono text-[10px] text-white/30">ESC</span></div><div className="py-3"><div className="px-3 pb-2 text-[9px] font-mono uppercase tracking-widest text-white/30">Global intelligence</div>{result.map(([a,b,I]) => { const Icon = I as typeof Users; return <button key={a as string} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left hover:bg-white/[.07]"><Icon size={15} className="text-[#b69de5]" /><span><span className="block text-xs font-semibold text-white">{a as string}</span><span className="block text-[10px] text-white/35">{b as string}</span></span><ArrowRight size={13} className="ml-auto text-white/25" /></button>; })}</div></div></div>; }

function StudentOverview({ go, missionDone }: { go: (p: string) => void; missionDone: boolean }) { const readiness = missionDone ? 79 : 72; return <><Title eyebrow="Student / overview" title="Good evening, Aanya." subtitle="Your skill signal is moving. Here is what changed across the ecosystem." action={<div className="flex gap-2"><Status tone="green">● System healthy</Status><Button variant="outline" onClick={() => go("skill-dna")}>Open Skill DNA <ArrowRight size={13} /></Button></div>} /><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Glass className="overflow-hidden p-0"><div className="grid gap-8 border-b border-white/10 p-5 md:grid-cols-[1fr_210px] md:p-7"><div><Eyebrow>Career signal / AI ML Engineer</Eyebrow><h2 className="mt-3 text-3xl font-bold tracking-[-.07em] text-white">Build proof, not just potential.</h2><p className="mt-4 max-w-lg text-sm leading-6 text-white/45">ShikshaSetu is mapping your evidence against the live role market. Your next best action is clear.</p><div className="mt-7 flex flex-wrap gap-2"><Status tone="red">Docker gap · 44%</Status><Status tone="violet">47 matched roles</Status><Status tone="green">18 verified skills</Status></div></div><div className="flex flex-col justify-end"><div className="flex items-end justify-between"><span className="text-[10px] text-white/35">Readiness</span><span className="font-mono text-4xl text-[#bca7e7]">{readiness}%</span></div><Progress value={readiness} /><span className="mt-2 text-right text-[10px] text-white/30">{missionDone ? "+7% after verified mission" : "+12% this month"}</span></div></div><div className="p-5 md:p-7"><div className="flex items-center justify-between"><div><Eyebrow>Evidence loop</Eyebrow><h3 className="mt-2 text-lg font-bold text-white">Your next unlock is one action away.</h3></div><button onClick={() => go("roadmap")} className="text-[10px] text-white/45">Open roadmap <ArrowRight size={12} className="ml-1 inline" /></button></div><div className="mt-6 flex items-center gap-2 overflow-x-auto pb-2">{["Skill gap", "ML API project", "Verified evidence", "Opportunity"].map((n, i) => <div key={n} className="flex shrink-0 items-center gap-2"><div className={`rounded-lg border px-3 py-3 ${i === 0 ? "border-[#bd9369]/45 bg-[#bd9369]/10" : i === 2 && missionDone ? "border-[#8eaa95]/35 bg-[#8eaa95]/10" : "border-white/10 bg-white/[.035]"}`}><div className="text-[10px] font-bold text-white">{n}</div><div className="mt-1 text-[9px] text-white/40">{i === 0 ? "Docker 31%" : i === 2 && missionDone ? "78% verified" : i === 3 ? `${missionDone ? 65 : 47} matches` : "next action"}</div></div>{i < 3 && <ArrowRight className="text-white/20" size={13} />}</div>)}</div></div></Glass><div className="space-y-5"><Glass className="p-5"><Eyebrow>Next best action</Eyebrow><h3 className="mt-3 text-lg font-bold text-white">Deploy an ML API with Docker</h3><p className="mt-2 text-xs leading-5 text-white/40">Generate verified deployment evidence and increase your demo readiness by 7 points.</p><Button className="mt-5 w-full" onClick={() => go("missions")}>{missionDone ? "View verified mission" : "Open industry mission"} <ArrowRight size={13} /></Button></Glass><Glass className="p-5"><div className="flex items-center justify-between"><Eyebrow>Opportunity stream</Eyebrow><button onClick={() => go("opportunities")} className="text-[10px] text-white/35">View all</button></div><div className="mt-4 flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#8eaa95]/15 text-[#a9c9ad]"><BriefcaseBusiness size={16} /></div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-white">AI / ML Intern</div><div className="mt-1 text-[10px] text-white/35">Nova Systems · {missionDone ? "96%" : "91%"} match</div></div><ChevronRight size={14} className="text-white/25" /></div></Glass></div></div></>; }

function SkillDNA({ missionDone, selectMission }: { missionDone: boolean; selectMission: (s: Skill) => void }) { const [selected, setSelected] = useState(skills[3]); const visible = skills.map(s => s.name === "Docker" && missionDone ? { ...s, current: 78, state: "verified", evidence: 4 } : s); return <><Title eyebrow="Student / intelligence" title="Skill DNA" subtitle="Your living capability profile — proficiency with provenance, not self-declaration." action={<Button variant="outline"><Fingerprint size={14} /> Share profile</Button>} /><div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><Glass className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-white/10 p-5 md:p-7"><div><Eyebrow>Aanya Sharma / capability map</Eyebrow><h2 className="mt-2 text-xl font-bold text-white">What you can demonstrate</h2></div><div className="flex gap-2"><Status tone="green">{missionDone ? "13 verified" : "12 verified"}</Status><Status tone="red">2 critical gaps</Status></div></div><div className="p-5 md:p-7"><div className="mb-3 grid grid-cols-[1.25fr_.55fr_.45fr_.4fr] gap-4 text-[9px] font-mono uppercase tracking-widest text-white/30"><span>Skill / category</span><span>Level</span><span>Confidence</span><span>Proof</span></div><div className="space-y-1">{visible.map(skill => <button key={skill.name} onClick={() => { setSelected(skill); selectMission(skill); }} className={`grid w-full grid-cols-[1.25fr_.55fr_.45fr_.4fr] items-center gap-4 rounded-lg p-3 text-left transition ${selected.name === skill.name ? "bg-white/[.08]" : "hover:bg-white/[.04]"}`}><div className="min-w-0"><div className="flex items-center gap-2"><span className="truncate text-xs font-bold text-white">{skill.name}</span><span className="hidden text-[9px] text-white/30 sm:inline">{skill.category}</span></div><div className="mt-2 max-w-[160px]"><Progress value={skill.current} color={skill.state === "critical gap" ? "bg-[#bd9369]" : skill.state === "verified" ? "bg-[#8eaf98]" : "bg-[#a890dc]"} /></div></div><div><span className="font-mono text-sm text-white">{skill.current}%</span><span className="ml-1 text-[9px] text-white/30">/ {skill.required}</span></div><div className="font-mono text-xs text-white/60">{skill.confidence}%</div><div className="flex items-center gap-1 font-mono text-xs text-white/60"><FileText size={12} />{skill.evidence}</div></button>)}</div></div></Glass><SkillPanel skill={selected} missionDone={missionDone} /></div></>; }
function SkillPanel({ skill, missionDone }: { skill: Skill; missionDone: boolean }) { const docker = skill.name === "Docker"; const current = docker && missionDone ? 78 : skill.current; return <Glass className="p-5 md:p-6"><Eyebrow>Skill intelligence / selected</Eyebrow><div className="mt-5 flex items-start justify-between"><div><h2 className="text-2xl font-bold tracking-[-.06em] text-white">{skill.name}</h2><div className="mt-1 text-xs text-white/40">{skill.category} · {docker && missionDone ? "verified" : skill.state}</div></div><Status tone={docker && missionDone ? "green" : skill.state === "critical gap" ? "red" : skill.state === "verified" ? "green" : "violet"}>{docker && missionDone ? "verified" : skill.state}</Status></div><div className="mt-7 grid grid-cols-3 gap-2"><Stat label="Current" value={`${current}%`} /><Stat label="Required" value={`${skill.required}%`} tone="violet" /><Stat label="Gap" value={`${Math.max(skill.required - current, 0)}%`} tone="amber" /></div><div className="mt-7 space-y-5 border-t border-white/10 pt-5"><div><Eyebrow>Why this matters</Eyebrow><p className="mt-2 text-xs leading-5 text-white/55">Production deployment is a major requirement across your target role and is requested by 37 companies in the demo demand graph.</p></div><div><Eyebrow>Evidence trail</Eyebrow><div className="mt-3 space-y-2">{(docker ? ["ML API project", "Docker assessment", "Mentor validation"] : ["Assessment result", "Project evidence", "Course completion"]).map((e, i) => <div key={e} className="flex items-center gap-2 text-xs text-white/65"><Check size={13} className="text-[#9bc4a3]" />{e}<span className="ml-auto text-[10px] text-white/30">{docker && missionDone ? "verified" : i === 0 ? skill.recency : "linked"}</span></div>)}</div></div><div><Eyebrow>Next best action</Eyebrow><p className="mt-2 text-xs leading-5 text-white/55">{docker && missionDone ? "Keep evidence fresh with a production deployment assessment." : "Deploy an ML API using Docker to create verified evidence."}</p></div><div className="flex items-center justify-between border-t border-white/10 pt-4"><span className="text-[10px] text-white/35">Opportunities unlocked</span><span className="font-mono text-xl text-[#c0aae8]">{docker && missionDone ? "18 → 65" : "+18"}</span></div></div></Glass>; }
function Stat({ label, value, tone = "neutral" }: { label: string; value: string; tone?: Tone }) { return <div className={`rounded-lg border p-3 ${tone === "violet" ? "border-[#a58cda]/25 bg-[#a58cda]/10" : tone === "amber" ? "border-[#bd9369]/25 bg-[#bd9369]/10" : "border-white/10 bg-white/[.035]"}`}><span className="text-[9px] text-white/40">{label}</span><b className={`mt-1 block font-mono text-xl ${tone === "violet" ? "text-[#c4b1e8]" : tone === "amber" ? "text-[#d6b67f]" : "text-white"}`}>{value}</b></div>; }

function Missions({ done, complete }: { done: boolean; complete: () => void }) { return <><Title eyebrow="Student / real-world evidence" title="Industry missions" subtitle="Turn a skill gap into proof that a company can trust." action={<Status tone={done ? "green" : "violet"}>{done ? "1 mission verified" : "3 available for you"}</Status>} /><div className="grid gap-5 xl:grid-cols-[1fr_.68fr]"><Glass className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-white/10 p-5"><div><Eyebrow>Recommended from your roadmap</Eyebrow><h2 className="mt-2 text-xl font-bold text-white">Build a document intelligence pipeline</h2></div><Status tone="amber">2 weeks</Status></div><div className="p-5"><div className="flex flex-wrap gap-2">{["Python", "LLMs", "Vector search", "Docker"].map(s => <Status key={s} tone={s === "Docker" && !done ? "amber" : "neutral"}>{s}</Status>)}</div><div className="mt-7 grid gap-5 border-y border-white/10 py-5 sm:grid-cols-3"><div><div className="text-[10px] text-white/35">Company</div><div className="mt-2 text-sm font-bold text-white">Nova Systems</div></div><div><div className="text-[10px] text-white/35">Evidence generated</div><div className="mt-2 text-sm font-bold text-white">Production project</div></div><div><div className="text-[10px] text-white/35">Opportunity impact</div><div className="mt-2 text-sm font-bold text-[#bca5e5]">+18 matches</div></div></div><p className="mt-5 max-w-xl text-sm leading-6 text-white/45">Ship a production-ready API that extracts structured knowledge from company documents. Your submission is assessed against real engineering criteria and can become verified portfolio evidence.</p><Button className="mt-6" onClick={complete}>{done ? <><Check size={13} /> Mission completed</> : <>Accept and complete demo mission <ArrowRight size={13} /></>}</Button></div></Glass><div className="space-y-5"><Glass className="p-5"><Eyebrow>Evidence chain</Eyebrow><h3 className="mt-3 text-lg font-bold text-white">Mission → skill → opportunity</h3><div className="mt-5 space-y-0">{[["Mission accepted", true], ["Submission evaluated", done], ["Docker evidence verified", done], ["18 roles unlocked", done]].map(([label, active], i) => <div key={label as string} className="flex gap-3"><div className="flex flex-col items-center"><div className={`flex h-6 w-6 items-center justify-center rounded-full border ${active ? "border-[#8eaa95]/60 bg-[#8eaa95]/15 text-[#acd0b2]" : "border-white/15 text-white/25"}`}>{active ? <Check size={12} /> : <span className="h-1.5 w-1.5 rounded-full bg-current" />}</div>{i < 3 && <div className={`h-8 w-px ${active ? "bg-[#8eaa95]/45" : "bg-white/10"}`} />}</div><div className="pt-1 text-xs text-white/60">{label as string}</div></div>)}</div></Glass><Glass className="p-5"><Eyebrow>Other missions</Eyebrow><div className="mt-4 space-y-3">{[["Deploy a model on AWS", "Cloud · 10 days"], ["Evaluate RAG hallucinations", "LLMs · 7 days"]].map(([a,b]) => <div key={a} className="flex items-center justify-between border-t border-white/10 pt-3"><div><div className="text-xs font-semibold text-white">{a}</div><div className="mt-1 text-[10px] text-white/35">{b}</div></div><ChevronRight size={14} className="text-white/25" /></div>)}</div></Glass></div></div></>; }

function Roadmap({ done }: { done: boolean }) { const base = [{ id: "goal", type: "graph", position: { x: 30, y: 200 }, data: { type: "goal", title: "AI / ML Engineer", meta: "career target", status: "verified" } }, { id: "ml", type: "graph", position: { x: 280, y: 90 }, data: { type: "skill", title: "Machine Learning", meta: "72% · in progress", status: "in progress" } }, { id: "docker", type: "graph", position: { x: 280, y: 300 }, data: { type: "skill", title: "Docker", meta: done ? "78% · verified" : "31% / 75% required", status: done ? "verified" : "critical gap" } }, { id: "project", type: "graph", position: { x: 560, y: 90 }, data: { type: "project", title: "Production ML API", meta: "3 weeks · recommended", status: "recommended" } }, { id: "mission", type: "graph", position: { x: 560, y: 300 }, data: { type: "mission", title: "Document pipeline", meta: done ? "completed · evidence" : "industry challenge", status: done ? "verified" : "locked" } }, { id: "outcome", type: "graph", position: { x: 840, y: 200 }, data: { type: "outcome", title: "Role ready", meta: done ? "65 opportunities" : "18 opportunities unlock", status: done ? "unlocked" : "locked" } }]; const [nodes, , onNodesChange] = useNodesState(base); const [edges, , onEdgesChange] = useEdgesState([{ id: "1", source: "goal", target: "ml", animated: true }, { id: "2", source: "goal", target: "docker", animated: true }, { id: "3", source: "ml", target: "project" }, { id: "4", source: "docker", target: "mission" }, { id: "5", source: "project", target: "outcome" }, { id: "6", source: "mission", target: "outcome" }]); const [selected, setSelected] = useState(base[2]); const type = useMemo(() => ({ graph: Node }), []); return <><Title eyebrow="Student / spatial intelligence" title="Career roadmap" subtitle="A living graph of skills, evidence and opportunities. Drag nodes to explore your pathway." action={<div className="flex gap-2"><Button variant="outline"><Plus size={13} /> Add node</Button><Button>Generate with profile <Sparkles size={13} /></Button></div>} /><div className="grid gap-5 xl:grid-cols-[1fr_330px]"><Glass className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-white/10 px-4 py-3"><span className="text-[10px] text-white/40">AI / ML Engineer · 6 month pathway</span><span className="font-mono text-[9px] text-white/30">{done ? "4 verified · 2 unlocked" : "1 verified · 1 critical gap"}</span></div><div className="h-[590px] bg-[#09090b]"><ReactFlow nodes={nodes} edges={edges} onNodesChange={onNodesChange} onEdgesChange={onEdgesChange} nodeTypes={type} onNodeClick={(_, n) => setSelected(n)} fitView proOptions={{ hideAttribution: true }}><Background color="#28252d" gap={28} size={1} /><Controls /><MiniMap nodeColor={(n: any) => n.data.status === "critical gap" ? "#b88c61" : n.data.status === "verified" ? "#8caf98" : "#8a73b0"} maskColor="rgba(8,8,9,.78)" /></ReactFlow></div></Glass><Glass className="p-5"><Eyebrow>Node intelligence</Eyebrow><Status tone={selected.data.status === "critical gap" ? "red" : selected.data.status === "verified" ? "green" : "violet"}>{selected.data.status}</Status><h2 className="mt-4 text-xl font-bold text-white">{selected.data.title}</h2><p className="mt-1 text-xs text-white/40">{selected.data.meta}</p><div className="mt-6 space-y-5 border-t border-white/10 pt-5"><div><Eyebrow>Relationship</Eyebrow><p className="mt-2 text-xs leading-5 text-white/50">This node connects your current capability to the next evidence and opportunity state.</p></div><div><Eyebrow>Expected impact</Eyebrow><p className="mt-2 font-mono text-xl text-[#c0aae8]">{selected.id === "docker" ? done ? "+7 readiness verified" : "+7 readiness" : "Downstream unlock"}</p></div></div><Button className="mt-7 w-full">Open intelligence panel <ArrowRight size={13} /></Button></Glass></div></>; }
function Node({ data }: any) { const status = data.status; const style = { border: status === "critical gap" ? "1px solid rgba(189,147,105,.7)" : status === "verified" ? "1px solid rgba(142,175,152,.55)" : "1px solid rgba(255,255,255,.15)", background: status === "critical gap" ? "#1c1711" : status === "verified" ? "#111b16" : "#141317", borderRadius: 10, color: "#f2f0ed", padding: 12, width: 178, boxShadow: "0 12px 30px rgba(0,0,0,.25)" }; return <div style={style}><Handle type="target" position={Position.Left} style={{ background: "#8e7cad", border: 0 }} /><div style={{ fontSize: 9, color: "rgba(255,255,255,.38)", textTransform: "uppercase", letterSpacing: ".14em", fontFamily: "DM Mono" }}>{data.type}</div><div style={{ fontSize: 12, fontWeight: 700, marginTop: 7 }}>{data.title}</div><div style={{ fontSize: 10, color: "rgba(255,255,255,.42)", marginTop: 4 }}>{data.meta}</div><Handle type="source" position={Position.Right} style={{ background: "#8e7cad", border: 0 }} /></div>; }

function CareerSimulator() { const [role, setRole] = useState(roles[0]); const [selected, setSelected] = useState([false, false, false]); const projected = role.readiness + selected.reduce((a, v, i) => a + (v ? [7, 9, 10][i] : 0), 0); return <><Title eyebrow="Student / decision intelligence" title="Career simulator" subtitle="Explore which pathway best fits your current evidence. Model outputs are estimates, not guarantees." action={<Status tone="violet">Demo model</Status>} /><div className="grid gap-5 xl:grid-cols-[.78fr_1.22fr]"><Glass className="p-6"><Eyebrow>Target role</Eyebrow><div className="mt-4 space-y-2">{roles.map(r => <button key={r.name} onClick={() => setRole(r)} className={`flex w-full items-center justify-between rounded-lg border p-4 text-left ${role.name === r.name ? "border-[#a58cda]/45 bg-[#a58cda]/10" : "border-white/10 bg-white/[.025]"}`}><div><div className="text-xs font-bold text-white">{r.name}</div><div className="mt-1 text-[10px] text-white/35">{r.gaps}</div></div><span className="font-mono text-sm text-[#c0aae8]">{r.readiness}%</span></button>)}</div><div className="mt-7 border-t border-white/10 pt-5"><Eyebrow>Role intelligence</Eyebrow><div className="mt-4 grid grid-cols-3 gap-2"><Stat label="Demand" value={role.demand} tone="green" /><Stat label="Open roles" value={`${role.opportunities}`} /><Stat label="Learning" value="16 wk" tone="amber" /></div></div></Glass><Glass className="p-6"><div className="flex items-end justify-between"><div><Eyebrow>Simulate pathway / {role.name}</Eyebrow><h2 className="mt-2 text-xl font-bold text-white">Current vs projected readiness</h2></div><div className="text-right"><div className="font-mono text-3xl text-[#c0aae8]">{projected}%</div><div className="text-[9px] text-white/35">projected</div></div></div><div className="mt-7 grid grid-cols-2 gap-3"><Stat label="Current readiness" value={`${role.readiness}%`} /><Stat label="Target readiness" value="85%" tone="violet" /></div><div className="mt-7 space-y-2">{[["Docker mission", "+7%"], ["AWS pathway", "+9%"], ["MLOps assessment", "+10%"]].map(([a,b], i) => <button key={a} onClick={() => setSelected(p => p.map((v,j) => j === i ? !v : v))} className={`flex w-full items-center gap-3 rounded-lg border p-4 text-left ${selected[i] ? "border-[#a58cda]/45 bg-[#a58cda]/10" : "border-white/10 bg-white/[.025]"}`}><span className={`flex h-5 w-5 items-center justify-center rounded border ${selected[i] ? "border-[#a58cda] bg-[#a58cda] text-black" : "border-white/20"}`}>{selected[i] && <Check size={12} />}</span><span className="flex-1 text-xs font-bold text-white">{a}</span><span className="font-mono text-xs text-[#c0aae8]">{b}</span></button>)}</div><div className="mt-6 rounded-lg border border-white/10 bg-white/[.025] p-4 text-[10px] leading-5 text-white/35">PROJECTED · MODEL ESTIMATE · NOT A GUARANTEE. The backend will later calculate this from evidence recency, assessments, role demand and opportunity eligibility.</div></Glass></div></>; }

function DataView({ role, page, go, missionDone, complete }: { role: Role; page: string; go: (p: string) => void; missionDone: boolean; complete: () => void }) { if (role === "student" && page === "overview") return <StudentOverview go={go} missionDone={missionDone} />; if (role === "student" && page === "skill-dna") return <SkillDNA missionDone={missionDone} selectMission={() => undefined} />; if (role === "student" && page === "missions") return <Missions done={missionDone} complete={complete} />; if (role === "student" && page === "roadmap") return <Roadmap done={missionDone} />; if (role === "student" && page === "career-simulator") return <CareerSimulator />; if (role === "institution" && page === "command-center") return <InstitutionCommand go={go} />; if (role === "institution" && page === "curriculum") return <Curriculum />; if (role === "institution" && page === "simulator") return <Simulator />; if (role === "industry" && page === "talent") return <Talent />; if (role === "faculty" && page === "passport") return <Passport />; return <ConnectedView role={role} page={page} go={go} missionDone={missionDone} />; }
function ConnectedView({ role, page, go, missionDone }: { role: Role; page: string; go: (p: string) => void; missionDone: boolean }) { const title = page.replace(/-/g, " "); const isEvidence = page === "evidence"; const isApplications = page === "applications" || page === "pipeline"; const isDemand = page === "demand" || page === "skill-intelligence"; const isAI = page === "ai-mentor"; const isLearning = page === "learning"; const isAssessment = page === "assessments"; return <><Title eyebrow={`${roleMeta[role].label} / connected workspace`} title={title} subtitle={isAI ? "Context-aware guidance grounded in your ShikshaSetu evidence and opportunity graph." : "A connected view of the same skill intelligence layer."} action={<Status tone="violet">Demo data · API-ready</Status>} /><div className="grid gap-5 xl:grid-cols-[1fr_.7fr]"><Glass className="overflow-hidden p-0"><div className="border-b border-white/10 p-5"><div className="flex items-center justify-between"><div><Eyebrow>{isDemand ? "Industry signals / 90 day movement" : isEvidence ? "Secure evidence vault" : isApplications ? "Lifecycle / current state" : "Recommended from your graph"}</Eyebrow><h2 className="mt-2 text-xl font-bold capitalize text-white">{isAI ? "What should I do this week?" : isEvidence ? "Provenance, permissions and verification" : isApplications ? "Opportunity lifecycle" : isDemand ? "MLOps is moving fastest" : isLearning ? "Next best learning actions" : isAssessment ? "Assessment center" : "Connected intelligence"}</h2></div><Button variant="outline"><Search size={13} /> Filter</Button></div></div>{isAI ? <div className="p-5 md:p-7"><div className="max-w-xl rounded-xl border border-[#a58cda]/25 bg-[#a58cda]/10 p-5"><div className="flex items-center gap-2 text-[10px] font-mono uppercase tracking-wider text-[#c3afe8]"><Sparkles size={13} /> AI mentor / grounded response</div><p className="mt-4 text-sm leading-7 text-white/75">Your highest-impact gap is Docker deployment. You are at 31%, while target roles require approximately 75%. Completing the recommended ML API deployment project could increase your demo readiness by approximately 7% and unlock 18 matching opportunities.</p><div className="mt-5 flex flex-wrap gap-2"><Button onClick={() => go("missions")}>Start project <ArrowRight size={13} /></Button><Button variant="outline" onClick={() => go("roadmap")}>View roadmap</Button></div></div></div> : isEvidence ? <Vault /> : isApplications ? <Lifecycle /> : isDemand ? <Demand /> : isLearning ? <Learning /> : isAssessment ? <Assessments /> : <ListPanel page={page} missionDone={missionDone} go={go} />}</Glass><Glass className="p-5"><Eyebrow>System context</Eyebrow><div className="mt-5 space-y-4">{[["Skill graph", "Docker → 4 roles → 219 opportunities"], ["Evidence", missionDone ? "Mission evidence verified" : "3 items awaiting verification"], ["Next action", "Deploy ML API with Docker"], ["Outcome signal", missionDone ? "65 matching roles" : "47 matching roles"]].map(([a,b], i) => <div key={a} className="border-t border-white/10 pt-4"><div className="text-[10px] text-white/35">{a}</div><div className={`mt-1 text-sm ${i === 3 && missionDone ? "text-[#a9c9ad]" : "text-white/70"}`}>{b}</div></div>)}</div><Button className="mt-7 w-full" onClick={() => go(role === "institution" ? "simulator" : role === "student" ? "missions" : "talent")}>Continue the loop <ArrowRight size={13} /></Button></Glass></div></>; }
function ListPanel({ page, missionDone, go }: { page: string; missionDone: boolean; go: (p: string) => void }) { const rows = page === "opportunities" ? [["AI / ML Intern", "Nova Systems", missionDone ? "96%" : "91%", "Docker"], ["Cloud Engineering Intern", "Orbit Labs", "78%", "AWS"], ["Data Engineering Project", "Nova Systems", "74%", "MLOps"]] : page === "mentors" ? [["Priya Menon", "MLOps · Nova Systems", "94% fit", "Available"], ["Dr. Kavita Rao", "Applied ML · Faculty", "88% fit", "2 slots"], ["Rahul Shah", "Cloud platforms · Alumni", "81% fit", "Available"]] : [["Production ML API", "Project evidence", "3 weeks", "+7 readiness"], ["Docker assessment", "Skill verification", "45 min", "+12 confidence"], ["Industry mentor review", "Evidence validation", "30 min", "Pending"]]; return <div className="divide-y divide-white/[.07]">{rows.map(r => <button key={r[0]} onClick={() => page === "opportunities" && go("applications")} className="flex w-full items-center gap-4 p-5 text-left hover:bg-white/[.04]"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-white/[.06] text-[#b8a2e5]"><BriefcaseBusiness size={15} /></div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-white">{r[0]}</div><div className="mt-1 text-[10px] text-white/35">{r[1]}</div></div><div className="hidden text-right sm:block"><div className="text-[9px] text-white/30">Signal</div><div className="mt-1 font-mono text-xs text-white/65">{r[2]}</div></div><span className="text-[10px] text-white/40">{r[3]}</span><ChevronRight size={14} className="text-white/25" /></button>)}</div>; }
function Vault() { return <div className="divide-y divide-white/[.07]">{[["ML API project report", "Project evidence · verified", "12 Jun 2025"], ["Docker assessment result", "Skill verification · verified", "09 Jun 2025"], ["Internship letter", "Experience · pending consent", "28 May 2025"], ["Mentor validation", "Recommendation · awaiting review", "24 May 2025"]].map((r, i) => <div key={r[0]} className="flex items-center gap-4 p-5"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-white/[.06] text-white/55"><FileCheck2 size={15} /></div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-white">{r[0]}</div><div className="mt-1 text-[10px] text-white/35">{r[1]}</div></div><span className="hidden text-[10px] text-white/35 sm:block">{r[2]}</span><Status tone={i < 2 ? "green" : "amber"}>{i < 2 ? "verified" : "review"}</Status></div>)}</div>; }
function Lifecycle() { return <div className="p-5 md:p-7"><div className="flex items-center justify-between overflow-x-auto pb-3">{["Applied", "Under review", "Shortlisted", "Interview", "Selected", "Completed"].map((s,i) => <div key={s} className="flex shrink-0 items-center"><div className={`flex items-center gap-2 ${i < 2 ? "text-white" : "text-white/30"}`}><span className={`flex h-7 w-7 items-center justify-center rounded-full border text-[10px] ${i < 2 ? "border-[#8eaa95]/50 bg-[#8eaa95]/15 text-[#acd0b2]" : "border-white/15"}`}>{i < 2 ? <Check size={12} /> : i + 1}</span><span className="text-[10px]">{s}</span></div>{i < 5 && <div className={`mx-3 h-px w-8 ${i < 1 ? "bg-[#8eaa95]/50" : "bg-white/10"}`} />}</div>)}</div><div className="mt-8 rounded-lg border border-white/10 bg-white/[.025] p-5"><div className="flex items-center justify-between"><div><div className="text-sm font-bold text-white">AI / ML Intern · Nova Systems</div><div className="mt-1 text-[10px] text-white/35">Applied 2 days ago · 91% explainable match</div></div><Status tone="green">under review</Status></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><Stat label="Skill compatibility" value="42 / 45" /><Stat label="Evidence quality" value="14 / 15" tone="violet" /><Stat label="Docker gap" value="44%" tone="amber" /></div></div></div>; }
function Demand() { const data = mockServices.getIndustryDemand(); return <div className="p-5 md:p-7"><div className="grid gap-4 md:grid-cols-3">{data.map((d,i) => <div key={d.skill} className="border-l border-white/10 pl-4"><div className="text-xs font-bold text-white">{d.skill}</div><div className="mt-3 flex items-end justify-between"><span className="font-mono text-3xl text-[#c0aae8]">{d.demand}%</span><span className="font-mono text-xs text-[#a9c9ad]">{d.change}</span></div><div className="mt-3 h-1 rounded bg-white/10"><div className={`h-full rounded ${i === 0 ? "bg-[#c0aae8]" : i === 1 ? "bg-[#8eaa95]" : "bg-[#b29363]"}`} style={{ width: `${d.demand}%` }} /></div><div className="mt-2 text-[10px] text-white/35">Student readiness {d.readiness}%</div></div>)}</div><div className="mt-8 border-t border-white/10 pt-6"><Eyebrow>Demand chain</Eyebrow><div className="mt-5 flex flex-wrap items-center gap-2">{["37 companies", "AI/ML Engineer", "MLOps", "Docker", "219 opportunities"].map((x,i) => <div key={x} className="flex items-center gap-2"><span className="rounded-lg border border-white/10 bg-white/[.035] px-3 py-2 text-[10px] text-white/65">{x}</span>{i < 4 && <ArrowRight size={12} className="text-white/25" />}</div>)}</div></div></div>; }
function Learning() { return <div className="divide-y divide-white/[.07]">{[["Deploy an ML API with Docker", "Closes Docker deployment gap", "+7% readiness", "3 weeks"], ["AWS Cloud Practitioner pathway", "Build cloud foundations", "+9% readiness", "4 weeks"], ["MLOps assessment prep", "Verify production lifecycle knowledge", "+10% confidence", "2 weeks"]].map(r => <div key={r[0]} className="flex flex-wrap items-center gap-4 p-5"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#a58cda]/15 text-[#c0aae8]"><BookOpen size={15} /></div><div className="min-w-[180px] flex-1"><div className="text-xs font-bold text-white">{r[0]}</div><div className="mt-1 text-[10px] text-white/35">{r[1]}</div></div><span className="font-mono text-xs text-[#c0aae8]">{r[2]}</span><span className="text-[10px] text-white/35">{r[3]}</span><ChevronRight size={14} className="text-white/25" /></div>)}</div>; }
function Assessments() { return <div className="grid gap-3 p-5 md:grid-cols-3 md:p-7">{[["Docker assessment", "Skill verification", "45 min", "31% → target 75%"], ["Role readiness", "AI / ML Engineer", "60 min", "54% current"], ["Communication signal", "Professional readiness", "30 min", "Completed"]].map(r => <div key={r[0]} className="rounded-lg border border-white/10 bg-white/[.025] p-4"><ShieldCheck size={16} className="text-[#b8a1e5]" /><h3 className="mt-6 text-sm font-bold text-white">{r[0]}</h3><p className="mt-1 text-[10px] text-white/35">{r[1]}</p><div className="mt-5 border-t border-white/10 pt-3 text-[10px] text-white/45">{r[2]} <span className="float-right text-white/65">{r[3]}</span></div><Button variant="outline" className="mt-4 w-full">Open assessment <ArrowRight size={12} /></Button></div>)}</div>; }

function InstitutionCommand({ go }: { go: (p: string) => void }) { const rows = [["MLOps", "34%", "81%", "412", "critical"], ["Generative AI", "42%", "94%", "388", "critical"], ["Cloud Computing", "51%", "88%", "286", "high"], ["Data Engineering", "68%", "84%", "196", "medium"]]; return <><Title eyebrow="Institution / command center" title="Discover gaps before placement season." subtitle="ShikshaSetu Institute of Technology · an institutional view of the shared skill graph." action={<Button onClick={() => go("simulator")}>What-If Simulator <ArrowRight size={13} /></Button>} /><div className="grid gap-3 md:grid-cols-4"><Stat label="Students" value="8,421" /><Stat label="Placement readiness" value="67%" tone="violet" /><Stat label="Industry aligned" value="71%" tone="green" /><Stat label="Active interventions" value="06" tone="amber" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Glass className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-white/10 p-5"><div><Eyebrow>Institutional signal</Eyebrow><h2 className="mt-2 text-lg font-bold text-white">Skill gap heatmap</h2></div><Status tone="red">3 critical gaps</Status></div><div className="overflow-x-auto p-5"><div className="min-w-[650px]"><div className="grid grid-cols-[1.3fr_repeat(3,1fr)_0.8fr] gap-2 pb-2 text-[9px] font-mono uppercase tracking-widest text-white/30"><span>Skill / demand</span><span>CSE 2027</span><span>IT 2027</span><span>ECE 2027</span><span>Affected</span></div>{rows.map(r => <button key={r[0]} onClick={() => go("skill-intelligence")} className="grid w-full grid-cols-[1.3fr_repeat(3,1fr)_0.8fr] gap-2 border-t border-white/[.07] py-3 text-left hover:bg-white/[.035]"><div><div className="text-xs font-bold text-white">{r[0]}</div><div className="mt-1 text-[9px] text-white/35">Demand {r[2]}</div></div>{[r[1], "39%", "28%"].map((v,i) => <div key={i} className={`rounded-md px-2 py-2 font-mono text-[10px] ${parseInt(v) < 40 ? "bg-[#b46e6e]/18 text-[#dc9b9b]" : "bg-[#b29363]/18 text-[#d8ba84]"}`}>{v}</div>)}<div className="py-2 font-mono text-[10px] text-white/55">{r[3]}</div></button>)}</div></div><div className="border-t border-white/10 px-5 py-3 text-[10px] text-white/35">Click a signal to move from institution → skill → intervention.</div></Glass><Glass className="p-5"><Eyebrow>Placement readiness</Eyebrow><div className="mt-5 flex h-44 items-end gap-2 border-b border-l border-white/10 px-3">{[40,44,48,52,58,62,67,70,72,75,81].map((h,i) => <div key={i} className="flex-1 rounded-t bg-[#a58cda]/55" style={{ height: `${h}%` }} />)}</div><div className="mt-3 flex justify-between text-[9px] text-white/30"><span>Jan</span><span>Now</span><span>Jun projection</span></div><div className="mt-6 border-t border-white/10 pt-5"><div className="text-[10px] text-white/35">Potential threshold crossings</div><div className="mt-2 font-mono text-2xl text-white">+214 <span className="text-xs text-[#a9c9ad]">with intervention</span></div></div></Glass></div></>; }
